update sys_employee
emp_no = #{empNo}, name = #{name}, gender = #{gender}, phone = #{phone}, email = #{email}, avatar = #{avatar}, dept_id = #{deptId}, job_title = #{jobTitle}, hire_date = #{hireDate}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}

update sys_employee
set last_login_time = #{lastLoginTime},
    last_login_ip   = #{lastLoginIp}
where id = #{id}

